```ts next-bound-frontend/src/app/store/userStore.ts
import { computed, inject } from "@angular/core";
import {
  addEntities,
  removeEntity,
  setAllEntities,
  updateEntity,
  withEntities,
} from "@ngrx/signals/entities";
import {
  patchState,
  signalStore,
  withComputed,
  withMethods,
  withState,
} from "@ngrx/signals";

import { AdmUserService } from "../administration/services/adm-user.service";

export interface User {
  id: number;
  username: string;
  email: string;
  password: string;
  role: "admin" | "user";
}

interface UserState {
  users: User[];
  state: "loading" | "loaded" | "error";
  filter: string;
}

const initialState: UserState = {
  users: [],
  state: "loading",
  filter: "",
};

export const userStore = signalStore(
  { providedIn: "root" },
  withState(initialState),
  withComputed(({ users }) => ({
    userCount: computed(() => users().length),
    singleUser: computed(() => users().filter((user) => user.id == 1)),
    adminList: computed(() => users().filter((user) => user.role == "admin")),
  })),
  withEntities<User>(),
  withMethods((store, admUserService = inject(AdmUserService)) => ({
    setUsers(users: User[]): void {
      patchState(store, setAllEntities(users));
    },

    addUser(user: User): void {
      patchState(store, addEntities([user]));
    },

    updateUser(user: Partial<User> & { id: number }): void {
      const { id, ...changes } = user;
      patchState(store, updateEntity({ id, changes }));
    },

    removeUser(userId: number): void {
      patchState(store, removeEntity(userId));
    },
  })),
);
```

crea un auth store basado en el user store, en cuanto a que se usta usando ngrx/signals
Para crear un `authStore` basado en el `userStore` utilizando `@ngrx/signals`, puedes seguir una estructura similar. El `authStore` puede manejar la autenticación del usuario, como el inicio de sesión, cierre de sesión y el estado de autenticación.

Aquí tienes un ejemplo de cómo podrías implementar el `authStore`:

```typescript
import { computed, inject } from "@angular/core";
import {
  patchState,
  signalStore,
  withComputed,
  withMethods,
  withState,
} from "@ngrx/signals";
import { AdmUserService } from "../administration/services/adm-user.service";
import { User, userStore } from "./userStore";

interface AuthState {
  currentUser: User | null;
  isAuthenticated: boolean;
  authState: "idle" | "authenticating" | "authenticated" | "error";
}

const initialAuthState: AuthState = {
  currentUser: null,
  isAuthenticated: false,
  authState: "idle",
};

export const authStore = signalStore(
  { providedIn: "root" },
  withState(initialAuthState),
  withComputed(({ currentUser }) => ({
    isAdmin: computed(() => currentUser()?.role === "admin"),
  })),
  withMethods((store, admUserService = inject(AdmUserService)) => ({
    login(username: string, password: string): void {
      patchState(store, { authState: "authenticating" });

      admUserService.login(username, password).subscribe({
        next(user) {
          patchState(store, {
            currentUser: user,
            isAuthenticated: true,
            authState: "authenticated",
          });
          userStore.setUsers([user]); // Optionally update userStore with the logged-in user
        },
        error() {
          patchState(store, { authState: "error" });
        },
      });
    },

    logout(): void {
      patchState(store, {
        currentUser: null,
        isAuthenticated: false,
        authState: "idle",
      });
    },

    setCurrentUser(user: User): void {
      patchState(store, {
        currentUser: user,
        isAuthenticated: true,
        authState: "authenticated",
      });
    },
  })),
);
```

En este ejemplo:

1. **Estado Inicial**: `initialAuthState` define el estado inicial del `authStore`.
2. **Computed Properties**: `withComputed` se usa para definir propiedades computadas, como `isAdmin`, que verifica si el usuario actual es un administrador.
3. **Métodos**: `withMethods` define los métodos para manejar la autenticación, como `login`, `logout` y `setCurrentUser`.

Para que esto funcione, necesitas asegurarte de que `AdmUserService` tenga un método `login` que devuelva un observable con el usuario autenticado. Aquí hay un ejemplo de cómo podría verse ese método en `AdmUserService`:

```typescript
import { HttpClient } from "@angular/common/http";
import { Injectable } from "@angular/core";
import { Observable } from "rxjs";
import { User } from "../../store/userStore";

@Injectable({
  providedIn: "root",
})
export class AdmUserService {
  constructor(private http: HttpClient) {}

  login(username: string, password: string): Observable<User> {
    return this.http.post<User>("http://localhost:3000/login", { username, password });
  }
}
```

Este es un ejemplo básico y puede necesitar ajustes según los detalles específicos de tu aplicación y API.
